  std::any nonce() override {
    return subtract(this->milliseconds(),
                    ::getValue(this->options, std::string("timeDifference")));
  }

  /**
   * @method
   * @name tokocrypto#fetchTime
   * @see https://www.tokocrypto.com/apidocs/#check-server-time
   * @description fetches the current integer timestamp in milliseconds from the
   * exchange server
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int} the current integer timestamp in milliseconds from the
   * exchange server
   */
  std::shared_future<std::any>
  fetchTime(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any response =
                            awaitValue(this->publicGetOpenV1CommonTime(params));
                        //
                        // {
                        //     "code": 0,
                        //     "msg": "Success",
                        //     "data": null,
                        //     "timestamp": 1737378074159
                        // }
                        //
                        return this->safeInteger(response,
                                                 std::string("timestamp"));
                      })
        .share();
  }

  /**
   * @method
   * @name tokocrypto#fetchMarkets
   * @see https://www.tokocrypto.com/apidocs/#get-all-supported-trading-symbol
   * @description retrieves data on all markets for tokocrypto
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<std::any>
  fetchMarkets(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any response =
                     awaitValue(this->publicGetOpenV1CommonSymbols(params));
                 //
                 //     {
                 //         "code":0,
                 //         "msg":"Success",
                 //         "data":{
                 //             "list":[
                 //                 {
                 //                     "type":1,
                 //                     "symbol":"1INCH_BTC",
                 //                     "baseAsset":"1INCH",
                 //                     "basePrecision":8,
                 //                     "quoteAsset":"BTC",
                 //                     "quotePrecision":8,
                 //                     "filters":[
                 //                         {"filterType":"PRICE_FILTER","minPrice":"0.00000001","maxPrice":"1000.00000000","tickSize":"0.00000001","applyToMarket":false},
                 //                         {"filterType":"PERCENT_PRICE","multiplierUp":5,"multiplierDown":0.2,"avgPriceMins":"5","applyToMarket":false},
                 //                         {"filterType":"LOT_SIZE","minQty":"0.10000000","maxQty":"90000000.00000000","stepSize":"0.10000000","applyToMarket":false},
                 //                         {"filterType":"MIN_NOTIONAL","avgPriceMins":"5","minNotional":"0.00010000","applyToMarket":true},
                 //                         {"filterType":"ICEBERG_PARTS","applyToMarket":false,"limit":"10"},
                 //                         {"filterType":"MARKET_LOT_SIZE","minQty":"0.00000000","maxQty":"79460.14117231","stepSize":"0.00000000","applyToMarket":false},
                 //                         {"filterType":"TRAILING_DELTA","applyToMarket":false},
                 //                         {"filterType":"MAX_NUM_ORDERS","applyToMarket":false},
                 //                         {"filterType":"MAX_NUM_ALGO_ORDERS","applyToMarket":false,"maxNumAlgoOrders":"5"}
                 //                     ],
                 //                     "orderTypes":["LIMIT","LIMIT_MAKER","MARKET","STOP_LOSS_LIMIT","TAKE_PROFIT_LIMIT"],
                 //                     "icebergEnable":1,
                 //                     "ocoEnable":1,
                 //                     "spotTradingEnable":1,
                 //                     "marginTradingEnable":1,
                 //                     "permissions":["SPOT","MARGIN"]
                 //                 },
                 //             ]
                 //         },
                 //         "timestamp":1659492212507
                 //     }
                 //
                 if (isTrue(isEqual(
                         ::getValue(this->options,
                                    std::string("adjustForTimeDifference")),
                         true))) {
                   awaitValue(this->loadTimeDifference());
                 }
                 std::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::dict{});
                 std::any list =
                     this->safeValue(data, std::string("list"), ccxt::list{});
                 std::any result = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(list));
                      postFixIncrement(i)) {
                   std::any market = ::getValue(list, i);
                   std::any baseId =
                       this->safeString(market, std::string("baseAsset"));
                   std::any quoteId =
                       this->safeString(market, std::string("quoteAsset"));
                   std::any id =
                       this->safeString(market, std::string("symbol"));
                   std::any lowercaseId =
                       this->safeStringLower(market, std::string("symbol"));
                   std::any settleId =
                       this->safeString(market, std::string("marginAsset"));
                   std::any base = this->safeCurrencyCode(baseId);
                   std::any quote = this->safeCurrencyCode(quoteId);
                   std::any settle = this->safeCurrencyCode(settleId);
                   std::any symbol = add(add(base, std::string("/")), quote);
                   std::any filters = this->safeValue(
                       market, std::string("filters"), ccxt::list{});
                   std::any filtersByType =
                       this->indexBy(filters, std::string("filterType"));
                   std::any status = this->safeString(
                       market, std::string("spotTradingEnable"));
                   std::any active = (isEqual(status, std::string("1")));
                   std::any permissions = this->safeValue(
                       market, std::string("permissions"), ccxt::list{});
                   for (std::any j = 0;
                        isLessThan(j, getArrayLength(permissions));
                        postFixIncrement(j)) {
                     if (isTrue(isEqual(::getValue(permissions, j),
                                        std::string("TRD_GRP_003")))) {
                       active = false;
                       break;
                     }
                   }
                   std::any marginTradingEnable = this->safeString(
                       market, std::string("marginTradingEnable"));
                   std::any entry = ccxt::dict{
                       {std::string("id"), id},
                       {std::string("lowercaseId"), lowercaseId},
                       {std::string("symbol"), symbol},
                       {std::string("base"), base},
                       {std::string("quote"), quote},
                       {std::string("settle"), settle},
                       {std::string("baseId"), baseId},
                       {std::string("quoteId"), quoteId},
                       {std::string("settleId"), settleId},
                       {std::string("type"), std::string("spot")},
                       {std::string("spot"), true},
                       {std::string("margin"),
                        (isEqual(marginTradingEnable, std::string("1")))},
                       {std::string("swap"), false},
                       {std::string("future"), false},
                       {std::string("delivery"), false},
                       {std::string("option"), false},
                       {std::string("active"), active},
                       {std::string("contract"), false},
                       {std::string("linear"), std::any{}},
                       {std::string("inverse"), std::any{}},
                       {std::string("contractSize"), std::any{}},
                       {std::string("expiry"), std::any{}},
                       {std::string("expiryDatetime"), std::any{}},
                       {std::string("strike"), std::any{}},
                       {std::string("optionType"), std::any{}},
                       {std::string("precision"),
                        ccxt::dict{
                            {std::string("amount"),
                             this->parseNumber(
                                 this->parsePrecision(this->safeString(
                                     market,
                                     std::string("quantityPrecision"))))},
                            {std::string("price"),
                             this->parseNumber(
                                 this->parsePrecision(this->safeString(
                                     market, std::string("pricePrecision"))))},
                            {std::string("base"),
                             this->parseNumber(
                                 this->parsePrecision(this->safeString(
                                     market, std::string("basePrecision"))))},
                            {std::string("quote"),
                             this->parseNumber(
                                 this->parsePrecision(this->safeString(
                                     market, std::string("quotePrecision"))))},
                        }},
                       {std::string("limits"),
                        ccxt::dict{
                            {std::string("leverage"),
                             ccxt::dict{
                                 {std::string("min"), std::any{}},
                                 {std::string("max"), std::any{}},
                             }},
                            {std::string("amount"),
                             ccxt::dict{
                                 {std::string("min"), std::any{}},
                                 {std::string("max"), std::any{}},
                             }},
                            {std::string("price"),
                             ccxt::dict{
                                 {std::string("min"), std::any{}},
                                 {std::string("max"), std::any{}},
                             }},
                            {std::string("cost"),
                             ccxt::dict{
                                 {std::string("min"), std::any{}},
                                 {std::string("max"), std::any{}},
                             }},
                        }},
                       {std::string("created"), std::any{}},
                       {std::string("info"), market},
                   };
                   if (isTrue(
                           inOp(filtersByType, std::string("PRICE_FILTER")))) {
                     std::any filter = this->safeValue(
                         filtersByType, std::string("PRICE_FILTER"),
                         ccxt::dict{});
                     ::setValue(
                         ::getValue(entry, std::string("precision")),
                         std::string("price"),
                         this->safeNumber(filter, std::string("tickSize")));
                     // PRICE_FILTER reports zero values for maxPrice
                     // since they updated filter types in November 2018
                     // https://github.com/ccxt/ccxt/issues/4286
                     // therefore limits['price']['max'] doesn't have any
                     // meaningful value except undefined
                     ::setValue(::getValue(entry, std::string("limits")),
                                std::string("price"),
                                ccxt::dict{
                                    {std::string("min"),
                                     this->safeNumber(filter,
                                                      std::string("minPrice"))},
                                    {std::string("max"),
                                     this->safeNumber(filter,
                                                      std::string("maxPrice"))},
                                });
                     ::setValue(::getValue(entry, std::string("precision")),
                                std::string("price"),
                                ::getValue(filter, std::string("tickSize")));
                   }
                   if (isTrue(inOp(filtersByType, std::string("LOT_SIZE")))) {
                     std::any filter = this->safeValue(
                         filtersByType, std::string("LOT_SIZE"), ccxt::dict{});
                     ::setValue(
                         ::getValue(entry, std::string("precision")),
                         std::string("amount"),
                         this->safeNumber(filter, std::string("stepSize")));
                     ::setValue(
                         ::getValue(entry, std::string("limits")),
                         std::string("amount"),
                         ccxt::dict{
                             {std::string("min"),
                              this->safeNumber(filter, std::string("minQty"))},
                             {std::string("max"),
                              this->safeNumber(filter, std::string("maxQty"))},
                         });
                   }
                   if (isTrue(inOp(filtersByType,
                                   std::string("MARKET_LOT_SIZE")))) {
                     std::any filter = this->safeValue(
                         filtersByType, std::string("MARKET_LOT_SIZE"),
                         ccxt::dict{});
                     ::setValue(
                         ::getValue(entry, std::string("limits")),
                         std::string("market"),
                         ccxt::dict{
                             {std::string("min"),
                              this->safeNumber(filter, std::string("minQty"))},
                             {std::string("max"),
                              this->safeNumber(filter, std::string("maxQty"))},
                         });
                   }
                   if (isTrue(
                           inOp(filtersByType, std::string("MIN_NOTIONAL")))) {
                     std::any filter = this->safeValue(
                         filtersByType, std::string("MIN_NOTIONAL"),
                         ccxt::dict{});
                     ::setValue(
                         ::getValue(::getValue(entry, std::string("limits")),
                                    std::string("cost")),
                         std::string("min"),
                         this->safeNumber2(filter, std::string("minNotional"),
                                           std::string("notional")));
                   }
                   arrayPush(result, entry);
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name tokocrypto#fetchOrderBook
   * @see https://www.tokocrypto.com/apidocs/#order-book
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return,
   * symbol type 3 markets accept 5, 10, 20, 50, 100, 500 or 1000 only
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<std::any>
  fetchOrderBook(std::any symbol, std::any limit = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any market = this->market(symbol);
                std::any request = ccxt::dict{
                    {std::string("symbol"), this->getMarketIdByType(market)},
                };
                if (isTrue(!isEqual(limit, std::any{}))) {
                  ::setValue(
                      request, std::string("limit"),
                      limit); // default 100, max 5000, see
                              // https://github.com/binance/binance-spot-api-docs/blob/master/rest-api.md#order-book
                }
                std::any response = std::any{};
                if (isTrue(this->isNativeMarket(market))) {
                  response = awaitValue(this->publicGetOpenV1MarketDepth(
                      this->extend(request, params)));
                } else {
                  response = awaitValue(
                      this->binanceGetDepth(this->extend(request, params)));
                }
                //
                // future
                //
                //     {
                //         "lastUpdateId":333598053905,
                //         "E":1618631511986,
                //         "T":1618631511964,
                //         "bids":[
                //             ["2493.56","20.189"],
                //             ["2493.54","1.000"],
                //             ["2493.51","0.005"]
                //         ],
                //         "asks":[
                //             ["2493.57","0.877"],
                //             ["2493.62","0.063"],
                //             ["2493.71","12.054"],
                //         ]
                //     }
                // type not 1
                //     {
                //         "code":0,
                //         "msg":"Success",
                //         "data":{
                //            "lastUpdateId":3204783,
                //            "bids":[],
                //            "asks": []
                //         },
                //         "timestamp":1692262634599
                //     }
                std::any data =
                    this->safeValue(response, std::string("data"), response);
                std::any timestamp = this->safeInteger2(
                    response, std::string("T"), std::string("timestamp"));
                std::any orderbook =
                    this->parseOrderBook(data, symbol, timestamp);
                ::setValue(
                    orderbook, std::string("nonce"),
                    this->safeInteger(data, std::string("lastUpdateId")));
                return orderbook;
              })
            .share();
  }

  std::any parseTrade(std::any trade, std::any market = std::any{}) override {
    //
    // aggregate trades
    // https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#compressedaggregate-trades-list
    //
    //     {
    //         "a": 26129,         // Aggregate tradeId
    //         "p": "0.01633102",  // Price
    //         "q": "4.70443515",  // Quantity
    //         "f": 27781,         // First tradeId
    //         "l": 27781,         // Last tradeId
    //         "T": 1498793709153, // Timestamp
    //         "m": true,          // Was the buyer the maker?
    //         "M": true           // Was the trade the best price match?
    //     }
    //
    // recent public trades and old public trades
    // https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#recent-trades-list
    // https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#old-trade-lookup-market_data
    //
    //     {
    //         "id": 28457,
    //         "price": "4.00000100",
    //         "qty": "12.00000000",
    //         "time": 1499865549590,
    //         "isBuyerMaker": true,
    //         "isBestMatch": true
    //     }
    //
    // private trades
    // https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#account-trade-list-user_data
    //
    //     {
    //         "symbol": "BNBBTC",
    //         "id": 28457,
    //         "orderId": 100234,
    //         "price": "4.00000100",
    //         "qty": "12.00000000",
    //         "commission": "10.10000000",
    //         "commissionAsset": "BNB",
    //         "time": 1499865549590,
    //         "isBuyer": true,
    //         "isMaker": false,
    //         "isBestMatch": true
    //     }
    //
    // futures trades
    // https://binance-docs.github.io/apidocs/futures/en/#account-trade-list-user_data
    //
    //     {
    //       "accountId": 20,
    //       "buyer": False,
    //       "commission": "-0.07819010",
    //       "commissionAsset": "USDT",
    //       "counterPartyId": 653,
    //       "id": 698759,
    //       "maker": False,
    //       "orderId": 25851813,
    //       "price": "7819.01",
    //       "qty": "0.002",
    //       "quoteQty": "0.01563",
    //       "realizedPnl": "-0.91539999",
    //       "side": "SELL",
    //       "symbol": "BTCUSDT",
    //       "time": 1569514978020
    //     }
    //     {
    //       "symbol": "BTCUSDT",
    //       "id": 477128891,
    //       "orderId": 13809777875,
    //       "side": "SELL",
    //       "price": "38479.55",
    //       "qty": "0.001",
    //       "realizedPnl": "-0.00009534",
    //       "marginAsset": "USDT",
    //       "quoteQty": "38.47955",
    //       "commission": "-0.00076959",
    //       "commissionAsset": "USDT",
    //       "time": 1612733566708,
    //       "positionSide": "BOTH",
    //       "maker": true,
    //       "buyer": false
    //     }
    //
    // { respType: FULL }
    //
    //     {
    //       "price": "4000.00000000",
    //       "qty": "1.00000000",
    //       "commission": "4.00000000",
    //       "commissionAsset": "USDT",
    //       "tradeId": "1234",
    //     }
    //
    std::any timestamp =
        this->safeInteger2(trade, std::string("T"), std::string("time"));
    std::any price =
        this->safeString2(trade, std::string("p"), std::string("price"));
    std::any amount =
        this->safeString2(trade, std::string("q"), std::string("qty"));
    std::any cost =
        this->safeString2(trade, std::string("quoteQty"),
                          std::string("baseQty")); // inverse futures
    std::any marketId = this->safeString(trade, std::string("symbol"));
    std::any symbol = this->safeSymbol(marketId, market);
    std::any id = this->safeString2(trade, std::string("t"), std::string("a"));
    id =
        this->safeString2(trade, std::string("id"), std::string("tradeId"), id);
    std::any side = std::any{};
    std::any orderId = this->safeString(trade, std::string("orderId"));
    std::any buyerMaker =
        this->safeValue2(trade, std::string("m"), std::string("isBuyerMaker"));
    std::any takerOrMaker = std::any{};
    if (isTrue(!isEqual(buyerMaker, std::any{}))) {
      side = (isTrue((isEqual(buyerMaker, true)))
                  ? std::any(std::string("sell"))
                  : std::any(
                        std::string("buy"))); // this is reversed intentionally
      takerOrMaker = std::string("taker");
    } else if (isTrue(inOp(trade, std::string("side")))) {
      side = this->safeStringLower(trade, std::string("side"));
    } else {
      if (isTrue(inOp(trade, std::string("isBuyer")))) {
        side =
            (isTrue((isEqual(::getValue(trade, std::string("isBuyer")), true)))
                 ? std::any(std::string("buy"))
                 : std::any(std::string("sell"))); // this is a true side
      }
    }
    std::any fee = std::any{};
    if (isTrue(inOp(trade, std::string("commission")))) {
      fee = ccxt::dict{
          {std::string("cost"),
           this->safeString(trade, std::string("commission"))},
          {std::string("currency"),
           this->safeCurrencyCode(
               this->safeString(trade, std::string("commissionAsset")))},
      };
    }
    if (isTrue(inOp(trade, std::string("isMaker")))) {
      takerOrMaker =
          (isTrue((isEqual(::getValue(trade, std::string("isMaker")), true)))
               ? std::any(std::string("maker"))
               : std::any(std::string("taker")));
    }
    if (isTrue(inOp(trade, std::string("maker")))) {
      takerOrMaker =
          (isTrue((isEqual(::getValue(trade, std::string("maker")), true)))
               ? std::any(std::string("maker"))
               : std::any(std::string("taker")));
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("id"), id},
            {std::string("order"), orderId},
            {std::string("type"), std::any{}},
            {std::string("side"), side},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("price"), price},
            {std::string("amount"), amount},
            {std::string("cost"), cost},
            {std::string("fee"), fee},
        },
        market);
  }

  /**
   * @method
   * @name tokocrypto#fetchTrades
   * @see https://www.tokocrypto.com/apidocs/#recent-trades-list
   * @see https://www.tokocrypto.com/apidocs/#compressedaggregate-trades-list
   * @description get the list of most recent trades for a particular symbol
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<std::any>
  fetchTrades(std::any symbol, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{};
                 // the venue routes market data by the symbol type reported by
                 // fetchMarkets, not by the quote currency: type 1 markets are
                 // served by the binance host with the underscore-less id,
                 // every other type by open/v1 with the raw id
                 ::setValue(request, std::string("symbol"),
                            this->getMarketIdByType(market));
                 if (isTrue(this->isNativeMarket(market))) {
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(request, std::string("limit"), limit);
                   }
                   // open/v1/market/trades answers an empty list for every
                   // market, the aggregate endpoint is the one that carries
                   // data for these markets
                   std::any responseInner =
                       awaitValue(this->publicGetOpenV1MarketAggTrades(
                           this->extend(request, params)));
                   //
                   //    {
                   //       "code": 0,
                   //       "msg": "Success",
                   //       "data": {
                   //           "list": [
                   //                {
                   //                    "a": 14433,             // aggregate
                   //                    tradeId "p": "495.00",          //
                   //                    price "q": "42.00000000",     //
                   //                    quantity "f": 15578,             //
                   //                    first tradeId "l": 15578, // last
                   //                    tradeId "T": 1787292236948,     //
                   //                    timestamp "m": false              //
                   //                    was the buyer the maker?
                   //                }
                   //            ]
                   //        },
                   //        "timestamp": 1787318052414
                   //    }
                   //
                   std::any data = this->safeDict(
                       responseInner, std::string("data"), ccxt::dict{});
                   std::any list =
                       this->safeList(data, std::string("list"), ccxt::list{});
                   return this->parseTrades(list, market, since, limit);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"),
                              limit); // default = 500, maximum = 1000
                 }
                 std::any defaultMethod = std::string("binanceGetTrades");
                 std::any method = this->safeString(
                     this->options, std::string("fetchTradesMethod"),
                     defaultMethod);
                 std::any response = std::any{};
                 if (isTrue(isTrue((isEqual(
                                method, std::string("binanceGetAggTrades")))) &&
                            isTrue((!isEqual(since, std::any{}))))) {
                   ::setValue(request, std::string("startTime"), since);
                   // https://github.com/ccxt/ccxt/issues/6400
                   // https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#compressedaggregate-trades-list
                   ::setValue(request, std::string("endTime"),
                              this->sum(since, 3600000));
                   response = awaitValue(this->binanceGetAggTrades(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->binanceGetTrades(this->extend(request, params)));
                 }
                 //
                 // Caveats:
                 // - default limit (500) applies only if no other parameters
                 // set, trades up
                 //   to the maximum limit may be returned to satisfy other
                 //   parameters
                 // - if both limit and time window is set and time window
                 // contains more
                 //   trades than the limit then the last trades from the window
                 //   are returned
                 // - 'tradeId' accepted and returned by this method is
                 // "aggregate" trade id
                 //   which is different from actual trade id
                 // - setting both fromId and time window results in error
                 //
                 // aggregate trades
                 //
                 //     [
                 //         {
                 //             "a": 26129,         // Aggregate tradeId
                 //             "p": "0.01633102",  // Price
                 //             "q": "4.70443515",  // Quantity
                 //             "f": 27781,         // First tradeId
                 //             "l": 27781,         // Last tradeId
                 //             "T": 1498793709153, // Timestamp
                 //             "m": true,          // Was the buyer the maker?
                 //             "M": true           // Was the trade the best
                 //             price match?
                 //         }
                 //     ]
                 //
                 // recent public trades and historical public trades
                 //
                 //     [
                 //         {
                 //             "id": 28457,
                 //             "price": "4.00000100",
                 //             "qty": "12.00000000",
                 //             "time": 1499865549590,
                 //             "isBuyerMaker": true,
                 //             "isBestMatch": true
                 //         }
                 //     ]
                 //
                 std::any responseList = this->toArray(response);
                 return this->parseTrades(responseList, market, since, limit);
               })
        .share();
  }

  std::any parseTicker(std::any ticker, std::any market = std::any{}) override {
    //
    //     {
    //         "symbol": "ETHBTC",
    //         "priceChange": "0.00068700",
    //         "priceChangePercent": "2.075",
    //         "weightedAvgPrice": "0.03342681",
    //         "prevClosePrice": "0.03310300",
    //         "lastPrice": "0.03378900",
    //         "lastQty": "0.07700000",
    //         "bidPrice": "0.03378900",
    //         "bidQty": "7.16800000",
    //         "askPrice": "0.03379000",
    //         "askQty": "24.00000000",
    //         "openPrice": "0.03310200",
    //         "highPrice": "0.03388900",
    //         "lowPrice": "0.03306900",
    //         "volume": "205478.41000000",
    //         "quoteVolume": "6868.48826294",
    //         "openTime": 1601469986932,
    //         "closeTime": 1601556386932,
    //         "firstId": 196098772,
    //         "lastId": 196186315,
    //         "count": 87544
    //     }
    //
    // coinm
    //     {
    //         "baseVolume": "214549.95171161",
    //         "closeTime": "1621965286847",
    //         "count": "1283779",
    //         "firstId": "152560106",
    //         "highPrice": "39938.3",
    //         "lastId": "153843955",
    //         "lastPrice": "37993.4",
    //         "lastQty": "1",
    //         "lowPrice": "36457.2",
    //         "openPrice": "37783.4",
    //         "openTime": "1621878840000",
    //         "pair": "BTCUSD",
    //         "priceChange": "210.0",
    //         "priceChangePercent": "0.556",
    //         "symbol": "BTCUSD_PERP",
    //         "volume": "81990451",
    //         "weightedAvgPrice": "38215.08713747"
    //     }
    //
    std::any timestamp = this->safeInteger(ticker, std::string("closeTime"));
    std::any marketId = this->safeString(ticker, std::string("symbol"));
    std::any symbol = this->safeSymbol(marketId, market);
    std::any last = this->safeString(ticker, std::string("lastPrice"));
    std::any isCoinm = (inOp(ticker, std::string("baseVolume")));
    std::any baseVolume = std::any{};
    std::any quoteVolume = std::any{};
    if (isTrue(isCoinm)) {
      baseVolume = this->safeString(ticker, std::string("baseVolume"));
      quoteVolume = this->safeString(ticker, std::string("volume"));
    } else {
      baseVolume = this->safeString(ticker, std::string("volume"));
      quoteVolume = this->safeString(ticker, std::string("quoteVolume"));
    }
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"),
             this->safeString(ticker, std::string("highPrice"))},
            {std::string("low"),
             this->safeString(ticker, std::string("lowPrice"))},
            {std::string("bid"),
             this->safeString(ticker, std::string("bidPrice"))},
            {std::string("bidVolume"),
             this->safeString(ticker, std::string("bidQty"))},
            {std::string("ask"),
             this->safeString(ticker, std::string("askPrice"))},
            {std::string("askVolume"),
             this->safeString(ticker, std::string("askQty"))},
            {std::string("vwap"),
             this->safeString(ticker, std::string("weightedAvgPrice"))},
            {std::string("open"),
             this->safeString(ticker, std::string("openPrice"))},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"),
             this->safeString(ticker, std::string("prevClosePrice"))},
            {std::string("change"),
             this->safeString(ticker, std::string("priceChange"))},
            {std::string("percentage"),
             this->safeString(ticker, std::string("priceChangePercent"))},
            {std::string("average"), std::any{}},
            {std::string("baseVolume"), baseVolume},
            {std::string("quoteVolume"), quoteVolume},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name tokocrypto#fetchTickers
   * @see
   * https://binance-docs.github.io/apidocs/spot/en/#24hr-ticker-price-change-statistics
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTickers(std::any symbols = std::any{},
               std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        // the binance backed host is the only source of 24hr
                        // statistics, so the result omits the native markets
                        // instead of raising for them, unlike the single symbol
                        // fetchTicker
                        std::any response =
                            awaitValue(this->binanceGetTicker24hr(params));
                        if (!isTrue(isArray(response))) {
                          // a user-supplied symbol param makes the endpoint
                          // answer a single ticker object, the unified
                          // fetchTickers contract returns a symbol-keyed dict
                          // either way
                          return this->parseTickers(ccxt::list{response},
                                                    symbols);
                        }
                        return this->parseTickers(response, symbols);
                      })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name tokocrypto#isNativeMarket
   * @description whether a market is served by the tokocrypto native endpoints
   * instead of the binance backed host
   * @param {object} market a unified market structure
   * @returns {boolean} true when the symbol type of the market is known and is
   * not 1
   */
  virtual std::any isNativeMarket(std::any market) {
    std::any marketInfo =
        this->safeDict(market, std::string("info"), ccxt::dict{});
    std::any symbolType = this->safeString(marketInfo, std::string("type"));
    // a market with an unknown symbol type falls back to the binance backed
    // host, the route that answers with data for every symbol type 1 market
    // and errors out loudly for the others, whereas open/v1 would answer an
    // empty list for them
    return isTrue((!isEqual(symbolType, std::any{}))) &&
           isTrue((!isEqual(symbolType, std::string("1"))));
  }

  /**
   * @ignore
   * @method
   * @name tokocrypto#getMarketIdByType
   * @description the market id spelling expected by the host that serves the
   * market
   * @param {object} market a unified market structure
   * @returns {string} the raw market id for native markets, the id without the
   * underscore separator otherwise
   */
  virtual std::any getMarketIdByType(std::any market) {
    if (isTrue(this->isNativeMarket(market))) {
      return this->safeString(market, std::string("id"));
    }
    return add(
        this->safeString(market, std::string("baseId"), std::string("")),
        this->safeString(market, std::string("quoteId"), std::string("")));
  }

  /**
   * @method
   * @name tokocrypto#fetchTicker
   * @see
   * https://binance-docs.github.io/apidocs/spot/en/#24hr-ticker-price-change-statistics
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTicker(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(this->isNativeMarket(market))) {
                   throw NotSupported(toString(add(
                       add(add(this->id,
                               std::string(" fetchTicker() does not support ")),
                           symbol),
                       std::string(
                           " yet, the venue serves 24hr ticker statistics only "
                           "for its binance backed markets"))));
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"), this->getMarketIdByType(market)},
                 };
                 std::any response = awaitValue(
                     this->binanceGetTicker24hr(this->extend(request, params)));
                 if (isTrue(isArray(response))) {
                   std::any firstTicker =
                       this->safeDict(response, 0, ccxt::dict{});
                   return this->parseTicker(firstTicker, market);
                 }
                 return this->parseTicker(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name tokocrypto#fetchBidsAsks
   * @see
   * https://binance-docs.github.io/apidocs/spot/en/#symbol-order-book-ticker
   * @description fetches the bid and ask price and volume for multiple markets
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the bids and asks for, all markets are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchBidsAsks(std::any symbols = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any response = awaitValue(
                            this->binanceGetTickerBookTicker(params));
                        return this->parseTickers(response, symbols);
                      })
        .share();
  }

  std::any parseOHLCV(std::any ohlcv, std::any market = std::any{}) override {
    // when api method = publicGetKlines || fapiPublicGetKlines ||
    // dapiPublicGetKlines
    //     [
    //         1591478520000, // open time
    //         "0.02501300",  // open
    //         "0.02501800",  // high
    //         "0.02500000",  // low
    //         "0.02500000",  // close
    //         "22.19000000", // volume
    //         1591478579999, // close time
    //         "0.55490906",  // quote asset volume
    //         40,            // number of trades
    //         "10.92900000", // taker buy base asset volume
    //         "0.27336462",  // taker buy quote asset volume
    //         "0"            // ignore
    //     ]
    //
    //  when api method = fapiPublicGetMarkPriceKlines ||
    //  fapiPublicGetIndexPriceKlines
    //     [
    //         [
    //         1591256460000,          // Open time
    //         "9653.29201333",        // Open
    //         "9654.56401333",        // High
    //         "9653.07367333",        // Low
    //         "9653.07367333",        // Close (or latest price)
    //         "0",                    // Ignore
    //         1591256519999,          // Close time
    //         "0",                    // Ignore
    //         60,                     // Number of basic data
    //         "0",                    // Ignore
    //         "0",                    // Ignore
    //         "0"                     // Ignore
    //         ]
    //     ]
    //
    return ccxt::list{this->safeInteger(ohlcv, 0), this->safeNumber(ohlcv, 1),
                      this->safeNumber(ohlcv, 2),  this->safeNumber(ohlcv, 3),
                      this->safeNumber(ohlcv, 4),  this->safeNumber(ohlcv, 5)};
  }

  /**
   * @method
   * @name tokocrypto#fetchOHLCV
   * @see https://binance-docs.github.io/apidocs/spot/en/#kline-candlestick-data
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.price] "mark" or "index" for mark price and index
   * price candles
   * @param {int} [params.until] timestamp in ms of the latest candle to fetch
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
             std::any since = std::any{}, std::any limit = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 // binance docs say that the default limit 500, max 1500 for
                 // futures, max 1000 for spot markets the reality is that the
                 // time range wider than 500 candles won't work right
                 std::any defaultLimit = 500;
                 std::any maxLimit = 1500;
                 std::any price =
                     this->safeString(params, std::string("price"));
                 std::any until =
                     this->safeInteger(params, std::string("until"));
                 params = this->omit(params, ccxt::list{std::string("price"),
                                                        std::string("until")});
                 limit = (isTrue((isEqual(limit, std::any{})))
                              ? std::any(defaultLimit)
                              : std::any(mathMin(limit, maxLimit)));
                 std::any request = ccxt::dict{
                     {std::string("interval"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                     {std::string("limit"), limit},
                 };
                 if (isTrue(isEqual(price, std::string("index")))) {
                   ::setValue(
                       request, std::string("pair"),
                       ::getValue(
                           market,
                           std::string("id"))); // Index price takes this
                                                // argument instead of symbol
                 } else {
                   ::setValue(request, std::string("symbol"),
                              this->getMarketIdByType(market));
                 }
                 // const duration = this.parseTimeframe (timeframe);
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(until, std::any{}))) {
                   ::setValue(request, std::string("endTime"), until);
                 }
                 std::any response = std::any{};
                 if (isTrue(this->isNativeMarket(market))) {
                   response = awaitValue(this->publicGetOpenV1MarketKlines(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->binanceGetKlines(this->extend(request, params)));
                 }
                 //
                 // binanceGetKlines
                 //
                 //     [
                 //         [1591478520000,"0.02501300","0.02501800","0.02500000","0.02500000","22.19000000",1591478579999,"0.55490906",40,"10.92900000","0.27336462","0"],
                 //         [1591478580000,"0.02499600","0.02500900","0.02499400","0.02500300","21.34700000",1591478639999,"0.53370468",24,"7.53800000","0.18850725","0"],
                 //         [1591478640000,"0.02500800","0.02501100","0.02500300","0.02500800","154.14200000",1591478699999,"3.85405839",97,"5.32300000","0.13312641","0"],
                 //     ]
                 //
                 // publicGetOpenV1MarketKlines
                 //
                 //     {
                 //         "code": 0,
                 //         "msg": "Success",
                 //         "data": [
                 //             [1787817600000,"521.00","537.00","521.00","537.00","1188.29000000",1787821199999,"632572.93",9,"1027.29000000","548331.93","0"],
                 //         ],
                 //         "timestamp": 1787822924930
                 //     }
                 //
                 // publicGetOpenV1MarketKlines, legacy envelope
                 //
                 //     {
                 //         "code": 0,
                 //         "msg": "Success",
                 //         "data": {
                 //             "list": [
                 //                 [1591478520000,"0.02501300","0.02501800","0.02500000","0.02500000","22.19000000",1591478579999,"0.55490906",40,"10.92900000","0.27336462","0"],
                 //             ]
                 //         },
                 //         "timestamp": 1659492212507
                 //     }
                 //
                 std::any data = ccxt::list{};
                 if (isTrue(isArray(response))) {
                   data = response;
                 } else {
                   std::any dataList =
                       this->safeList(response, std::string("data"));
                   if (isTrue(!isEqual(dataList, std::any{}))) {
                     data = dataList;
                   } else {
                     std::any dataDict = this->safeDict(
                         response, std::string("data"), ccxt::dict{});
                     data = this->safeList(dataDict, std::string("list"),
                                           ccxt::list{});
                   }
                 }
                 return this->parseOHLCVs(data, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  /**
   * @method
   * @name tokocrypto#fetchBalance
   * @see https://www.tokocrypto.com/apidocs/#account-information-signedFlag
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.type] 'future', 'delivery', 'savings', 'funding',
   * or 'spot'
   * @param {string} [params.marginMode] 'cross' or 'isolated', for margin
   * trading, uses ::getValue(this, std::string("options")).defaultMarginMode if
   * not passed, defaults to undefined/None/null
   * @param {string[]|undefined} [::getValue(params, std::string("symbols"))]
   * unified market symbols, only used in isolated margin mode
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<std::any>
  fetchBalance(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any defaultType = this->safeString2(
                     this->options, std::string("fetchBalance"),
                     std::string("defaultType"), std::string("spot"));
                 std::any type =
                     this->safeString(params, std::string("type"), defaultType);
                 std::any defaultMarginMode =
                     this->safeString2(this->options, std::string("marginMode"),
                                       std::string("defaultMarginMode"));
                 std::any marginMode = this->safeStringLower(
                     params, std::string("marginMode"), defaultMarginMode);
                 std::any request = ccxt::dict{};
                 std::any response =
                     awaitValue(this->privateGetOpenV1AccountSpot(
                         this->extend(request, params)));
                 //
                 // spot
                 //
                 //     {
                 //         "code":0,
                 //         "msg":"Success",
                 //         "data":{
                 //             "makerCommission":"0.00100000",
                 //             "takerCommission":"0.00100000",
                 //             "buyerCommission":"0.00000000",
                 //             "sellerCommission":"0.00000000",
                 //             "canTrade":1,
                 //             "canWithdraw":1,
                 //             "canDeposit":1,
                 //             "status":1,
                 //             "accountAssets":[
                 //                 {"asset":"1INCH","free":"0","locked":"0"},
                 //                 {"asset":"AAVE","free":"0","locked":"0"},
                 //                 {"asset":"ACA","free":"0","locked":"0"}
                 //             ],
                 //         },
                 //         "timestamp":1659666786943
                 //     }
                 //
                 return this->parseBalanceCustom(response, type, marginMode);
               })
        .share();
  }

  virtual std::any parseBalanceCustom(std::any response,
                                      std::any type = std::any{},
                                      std::any marginMode = std::any{}) {
    std::any timestamp = this->safeInteger(response, std::string("updateTime"));
    std::any result = ccxt::dict{
        {std::string("info"), response},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
    };
    std::any data =
        this->safeValue(response, std::string("data"), ccxt::dict{});
    std::any balances =
        this->safeValue(data, std::string("accountAssets"), ccxt::list{});
    for (std::any i = 0; isLessThan(i, getArrayLength(balances));
         postFixIncrement(i)) {
      std::any balance = ::getValue(balances, i);
      std::any currencyId = this->safeString(balance, std::string("asset"));
      std::any code = this->safeCurrencyCode(currencyId);
      std::any account = this->account();
      ::setValue(account, std::string("free"),
                 this->safeString(balance, std::string("free")));
      ::setValue(account, std::string("used"),
                 this->safeString(balance, std::string("locked")));
      if (isTrue(!isEqual(code, std::any{}))) {
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

  virtual std::any parseOrderStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("-2"), std::string("open")},
        {std::string("0"), std::string("open")},
        {std::string("1"), std::string("open")},
        {std::string("2"), std::string("closed")},
        {std::string("3"), std::string("canceled")},
        {std::string("4"), std::string("canceling")},
        {std::string("5"), std::string("rejected")},
        {std::string("6"), std::string("expired")},
        {std::string("NEW"), std::string("open")},
        {std::string("PARTIALLY_FILLED"), std::string("open")},
        {std::string("FILLED"), std::string("closed")},
        {std::string("CANCELED"), std::string("canceled")},
        {std::string("PENDING_CANCEL"), std::string("canceling")},
        {std::string("REJECTED"), std::string("rejected")},
        {std::string("EXPIRED"), std::string("expired")},
    };
    return this->safeString(statuses, status, status);
  }

  std::any parseOrder(std::any order, std::any market = std::any{}) override {
    //
    // spot
    //
    //     {
    //         "symbol": "LTCBTC",
    //         "orderId": 1,
    //         "clientOrderId": "myOrder1",
    //         "price": "0.1",
    //         "origQty": "1.0",
    //         "executedQty": "0.0",
    //         "cummulativeQuoteQty": "0.0",
    //         "status": "NEW",
    //         "timeInForce": "GTC",
    //         "type": "LIMIT",
    //         "side": "BUY",
    //         "stopPrice": "0.0",
    //         "icebergQty": "0.0",
    //         "time": 1499827319559,
    //         "updateTime": 1499827319559,
    //         "isWorking": true
    //     }
    // createOrder
    //     {
    //         "orderId": "145265071",
    //         "bOrderListId": "0",
    //         "clientId": "49c09c3c2cd54419a59c05441f517b3c",
    //         "bOrderId": "35247529",
    //         "symbol": "USDT_BIDR",
    //         "symbolType": "1",
    //         "side": "0",
    //         "type": "1",
    //         "price": "11915",
    //         "origQty": "2",
    //         "origQuoteQty": "23830.00",
    //         "executedQty": "0.00000000",
    //         "executedPrice": "0",
    //         "executedQuoteQty": "0.00",
    //         "timeInForce": "1",
    //         "stopPrice": "0",
    //         "icebergQty": "0",
    //         "status": "0",
    //         "createTime": "1662711074372"
    //     }
    //
    // createOrder with { "newOrderRespType": "FULL" }
    //
    //     {
    //       "symbol": "BTCUSDT",
    //       "orderId": 5403233939,
    //       "orderListId": -1,
    //       "clientOrderId": "x-R4BD3S825e669e75b6c14f69a2c43e",
    //       "transactTime": 1617151923742,
    //       "price": "0.00000000",
    //       "origQty": "0.00050000",
    //       "executedQty": "0.00050000",
    //       "cummulativeQuoteQty": "29.47081500",
    //       "status": "FILLED",
    //       "timeInForce": "GTC",
    //       "type": "MARKET",
    //       "side": "BUY",
    //       "fills": [
    //         {
    //           "price": "58941.63000000",
    //           "qty": "0.00050000",
    //           "commission": "0.00007050",
    //           "commissionAsset": "BNB",
    //           "tradeId": 737466631
    //         }
    //       ]
    //     }
    //
    // delivery
    //
    //     {
    //       "orderId": "18742727411",
    //       "symbol": "ETHUSD_PERP",
    //       "pair": "ETHUSD",
    //       "status": "FILLED",
    //       "clientOrderId": "x-xcKtGhcu3e2d1503fdd543b3b02419",
    //       "price": "0",
    //       "avgPrice": "4522.14",
    //       "origQty": "1",
    //       "executedQty": "1",
    //       "cumBase": "0.00221134",
    //       "timeInForce": "GTC",
    //       "type": "MARKET",
    //       "reduceOnly": false,
    //       "closePosition": false,
    //       "side": "SELL",
    //       "positionSide": "BOTH",
    //       "stopPrice": "0",
    //       "workingType": "CONTRACT_PRICE",
    //       "priceProtect": false,
    //       "origType": "MARKET",
    //       "time": "1636061952660",
    //       "updateTime": "1636061952660"
    //     }
    //
    std::any status =
        this->parseOrderStatus(this->safeString(order, std::string("status")));
    std::any marketId = this->safeString(order, std::string("symbol"));
    std::any symbol = this->safeSymbol(marketId, market);
    std::any filled =
        this->safeString(order, std::string("executedQty"), std::string("0"));
    std::any timestamp = this->safeInteger(order, std::string("createTime"));
    std::any average = this->safeString(order, std::string("avgPrice"));
    std::any price = this->safeString2(order, std::string("price"),
                                       std::string("executedPrice"));
    std::any amount = this->safeString(order, std::string("origQty"));
    // - Spot/Margin market: cummulativeQuoteQty
    //   Note this is not the actual cost, since Binance futures uses leverage
    //   to calculate margins.
    std::any cost = this->safeStringN(
        order,
        ccxt::list{std::string("cummulativeQuoteQty"), std::string("cumQuote"),
                   std::string("executedQuoteQty"), std::string("cumBase")});
    std::any id = this->safeString(order, std::string("orderId"));
    std::any type =
        this->parseOrderType(this->safeStringLower(order, std::string("type")));
    std::any side = this->safeStringLower(order, std::string("side"));
    if (isTrue(isEqual(side, std::string("0")))) {
      side = std::string("buy");
    } else if (isTrue(isEqual(side, std::string("1")))) {
      side = std::string("sell");
    }
    std::any fills = this->safeValue(order, std::string("fills"), ccxt::list{});
    std::any clientOrderId = this->safeString2(
        order, std::string("clientOrderId"), std::string("clientId"));
    std::any timeInForce = this->safeString(order, std::string("timeInForce"));
    if (isTrue(isEqual(timeInForce, std::string("GTX")))) {
      // GTX means "Good Till Crossing" and is an equivalent way of saying Post
      // Only
      timeInForce = std::string("PO");
    }
    std::any postOnly = isTrue((isEqual(type, std::string("limit_maker")))) ||
                        isTrue((isEqual(timeInForce, std::string("PO"))));
    return this->safeOrder(
        ccxt::dict{
            {std::string("info"), order},
            {std::string("id"), id},
            {std::string("clientOrderId"), clientOrderId},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), std::any{}},
            {std::string("symbol"), symbol},
            {std::string("type"), type},
            {std::string("timeInForce"), timeInForce},
            {std::string("postOnly"), postOnly},
            {std::string("reduceOnly"),
             this->safeValue(order, std::string("reduceOnly"))},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("triggerPrice"),
             this->parseNumber(this->omitZero(
                 this->safeString(order, std::string("stopPrice"))))},
            {std::string("amount"), amount},
            {std::string("cost"), cost},
            {std::string("average"), average},
            {std::string("filled"), filled},
            {std::string("remaining"), std::any{}},
            {std::string("status"), status},
            {std::string("fee"), std::any{}},
            {std::string("trades"), fills},
        },
        market);
  }

  virtual std::any parseOrderType(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("2"), std::string("market")},
        {std::string("1"), std::string("limit")},
        {std::string("4"), std::string("limit")},
        {std::string("7"), std::string("limit")},
    };
    return this->safeString(statuses, status, status);
  }

  /**
   * @method
   * @name tokocrypto#createOrder
   * @description create a trade order
   * @see https://www.tokocrypto.com/apidocs/#new-order--signedFlag
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.triggerPrice] the price at which a trigger order
   * would be triggered
   * @param {float} [params.cost] for spot market buy orders, the quote quantity
   * that can be used as an alternative for the amount
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any clientOrderId =
                     this->safeString2(params, std::string("clientOrderId"),
                                       std::string("clientId"));
                 std::any postOnly =
                     this->safeBool(params, std::string("postOnly"), false);
                 // only supported for spot/margin api
                 if (isTrue(isEqual(postOnly, true))) {
                   type = std::string("LIMIT_MAKER");
                 }
                 params = this->omit(params,
                                     ccxt::list{std::string("clientId"),
                                                std::string("clientOrderId")});
                 std::any initialUppercaseType = toUpperCase(type);
                 std::any uppercaseType = initialUppercaseType;
                 std::any triggerPrice =
                     this->safeValue2(params, std::string("triggerPrice"),
                                      std::string("stopPrice"));
                 if (isTrue(!isEqual(triggerPrice, std::any{}))) {
                   params = this->omit(params,
                                       ccxt::list{std::string("triggerPrice"),
                                                  std::string("stopPrice")});
                   if (isTrue(isEqual(uppercaseType, std::string("MARKET")))) {
                     uppercaseType = std::string("STOP_LOSS");
                   } else if (isTrue(isEqual(uppercaseType,
                                             std::string("LIMIT")))) {
                     uppercaseType = std::string("STOP_LOSS_LIMIT");
                   }
                 }
                 std::any validOrderTypes =
                     this->safeValue(::getValue(market, std::string("info")),
                                     std::string("orderTypes"));
                 if (!isTrue(this->inArray(uppercaseType, validOrderTypes))) {
                   if (isTrue(!isEqual(initialUppercaseType, uppercaseType))) {
                     throw InvalidOrder(toString(add(
                         add(add(add(add(this->id,
                                         std::string(" triggerPrice parameter "
                                                     "is not allowed for ")),
                                     symbol),
                                 std::string(" ")),
                             type),
                         std::string(" orders"))));
                   } else {
                     throw InvalidOrder(toString(add(
                         add(add(add(add(this->id, std::string(" ")), type),
                                 std::string(
                                     " is not a valid order type for the ")),
                             symbol),
                         std::string(" market"))));
                   }
                 }
                 std::any reverseOrderTypeMapping = ccxt::dict{
                     {std::string("LIMIT"), 1},
                     {std::string("MARKET"), 2},
                     {std::string("STOP_LOSS"), 3},
                     {std::string("STOP_LOSS_LIMIT"), 4},
                     {std::string("TAKE_PROFIT"), 5},
                     {std::string("TAKE_PROFIT_LIMIT"), 6},
                     {std::string("LIMIT_MAKER"), 7},
                 };
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      add(add(::getValue(market, std::string("baseId")),
                              std::string("_")),
                          ::getValue(market, std::string("quoteId")))},
                     {std::string("type"),
                      this->safeString(reverseOrderTypeMapping, uppercaseType)},
                 };
                 if (isTrue(isEqual(side, std::string("buy")))) {
                   ::setValue(request, std::string("side"), 0);
                 } else if (isTrue(isEqual(side, std::string("sell")))) {
                   ::setValue(request, std::string("side"), 1);
                 }
                 if (isTrue(isEqual(clientOrderId, std::any{}))) {
                   std::any broker =
                       this->safeValue(this->options, std::string("broker"));
                   if (isTrue(!isEqual(broker, std::any{}))) {
                     std::any brokerId =
                         this->safeString(broker, std::string("marketType"));
                     if (isTrue(!isEqual(brokerId, std::any{}))) {
                       ::setValue(request, std::string("clientId"),
                                  add(brokerId, this->uuid22()));
                     }
                   }
                 } else {
                   ::setValue(request, std::string("clientId"), clientOrderId);
                 }
                 // additional required fields depending on the order type
                 std::any priceIsRequired = false;
                 std::any triggerPriceIsRequired = false;
                 std::any quantityIsRequired = false;
                 //
                 // spot/margin
                 //
                 //     LIMIT                timeInForce, quantity, price
                 //     MARKET               quantity or quoteOrderQty
                 //     STOP_LOSS            quantity, stopPrice
                 //     STOP_LOSS_LIMIT      timeInForce, quantity, price,
                 //     stopPrice TAKE_PROFIT          quantity, stopPrice
                 //     TAKE_PROFIT_LIMIT    timeInForce, quantity, price,
                 //     stopPrice LIMIT_MAKER          quantity, price
                 //
                 if (isTrue(isEqual(uppercaseType, std::string("MARKET")))) {
                   if (isTrue(isEqual(side, std::string("buy")))) {
                     std::any precision = ::getValue(
                         ::getValue(market, std::string("precision")),
                         std::string("price"));
                     std::any quoteAmount = std::any{};
                     std::any createMarketBuyOrderRequiresPrice = true;
                     std::any createMarketBuyOrderRequiresPriceparamsVariable =
                         this->handleOptionAndParams(
                             params, std::string("createOrder"),
                             std::string("createMarketBuyOrderRequiresPrice"),
                             true);
                     createMarketBuyOrderRequiresPrice = ::getValue(
                         createMarketBuyOrderRequiresPriceparamsVariable, 0);
                     params = ::getValue(
                         createMarketBuyOrderRequiresPriceparamsVariable, 1);
                     std::any cost =
                         this->safeNumber2(params, std::string("cost"),
                                           std::string("quoteOrderQty"));
                     params = this->omit(
                         params, ccxt::list{std::string("cost"),
                                            std::string("quoteOrderQty")});
                     if (isTrue(!isEqual(cost, std::any{}))) {
                       quoteAmount = cost;
                     } else if (isTrue(createMarketBuyOrderRequiresPrice)) {
                       if (isTrue(isEqual(price, std::any{}))) {
                         throw InvalidOrder(toString(add(
                             this->id,
                             std::string(
                                 " createOrder() requires the price argument "
                                 "for market buy orders to calculate the total "
                                 "cost to spend (amount * price), "
                                 "alternatively set the "
                                 "createMarketBuyOrderRequiresPrice option or "
                                 "param to false and pass the cost to spend "
                                 "(quote quantity) in the amount argument"))));
                       } else {
                         std::any amountString = this->numberToString(amount);
                         std::any priceString = this->numberToString(price);
                         quoteAmount = ccxt::Precise::stringMul(amountString,
                                                                priceString);
                       }
                     } else {
                       quoteAmount = amount;
                     }
                     ::setValue(request, std::string("quoteOrderQty"),
                                this->decimalToPrecision(quoteAmount, TRUNCATE,
                                                         precision,
                                                         this->precisionMode));
                   } else {
                     quantityIsRequired = true;
                   }
                 } else if (isTrue(
                                isEqual(uppercaseType, std::string("LIMIT")))) {
                   priceIsRequired = true;
                   quantityIsRequired = true;
                 } else if (isTrue(
                                isTrue((isEqual(uppercaseType,
                                                std::string("STOP_LOSS")))) ||
                                isTrue(
                                    (isEqual(uppercaseType,
                                             std::string("TAKE_PROFIT")))))) {
                   triggerPriceIsRequired = true;
                   quantityIsRequired = true;
                   if (isTrue(isTrue((isEqual(
                                  ::getValue(market, std::string("linear")),
                                  true))) ||
                              isTrue((isEqual(
                                  ::getValue(market, std::string("inverse")),
                                  true))))) {
                     priceIsRequired = true;
                   }
                 } else if (isTrue(isTrue((isEqual(
                                       uppercaseType,
                                       std::string("STOP_LOSS_LIMIT")))) ||
                                   isTrue((isEqual(
                                       uppercaseType,
                                       std::string("TAKE_PROFIT_LIMIT")))))) {
                   quantityIsRequired = true;
                   triggerPriceIsRequired = true;
                   priceIsRequired = true;
                 } else if (isTrue(isEqual(uppercaseType,
                                           std::string("LIMIT_MAKER")))) {
                   priceIsRequired = true;
                   quantityIsRequired = true;
                 }
                 if (isTrue(quantityIsRequired)) {
                   ::setValue(request, std::string("quantity"),
                              this->amountToPrecision(symbol, amount));
                 }
                 if (isTrue(priceIsRequired)) {
                   if (isTrue(isEqual(price, std::any{}))) {
                     throw InvalidOrder(toString(
                         add(add(add(this->id,
                                     std::string(" createOrder() requires a "
                                                 "price argument for a ")),
                                 type),
                             std::string(" order"))));
                   }
                   ::setValue(request, std::string("price"),
                              this->priceToPrecision(symbol, price));
                 }
                 if (isTrue(triggerPriceIsRequired)) {
                   if (isTrue(isEqual(triggerPrice, std::any{}))) {
                     throw InvalidOrder(toString(
                         add(add(add(this->id,
                                     std::string(
                                         " createOrder() requires a "
                                         "triggerPrice extra param for a ")),
                                 type),
                             std::string(" order"))));
                   } else {
                     ::setValue(request, std::string("stopPrice"),
                                this->priceToPrecision(symbol, triggerPrice));
                   }
                 }
                 std::any response = awaitValue(this->privatePostOpenV1Orders(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "code": 0,
                 //         "msg": "Success",
                 //         "data": {
                 //             "orderId": 145264846,
                 //             "bOrderListId": 0,
                 //             "clientId": "4ee2ab5e55e74b358eaf98079c670d17",
                 //             "bOrderId": 35247499,
                 //             "symbol": "USDT_BIDR",
                 //             "symbolType": 1,
                 //             "side": 0,
                 //             "type": 1,
                 //             "price": "11915",
                 //             "origQty": "2",
                 //             "origQuoteQty": "23830.00",
                 //             "executedQty": "0.00000000",
                 //             "executedPrice": "0",
                 //             "executedQuoteQty": "0.00",
                 //             "timeInForce": 1,
                 //             "stopPrice": 0,
                 //             "icebergQty": "0",
                 //             "status": 0,
                 //             "createTime": 1662710994848
                 //         },
                 //         "timestamp": 1662710994975
                 //     }
                 //
                 std::any rawOrder = this->safeDict(
                     response, std::string("data"), ccxt::dict{});
                 return this->parseOrder(rawOrder, market);
               })
        .share();
  }

  /**
   * @method
   * @name tokocrypto#fetchOrder
   * @see https://www.tokocrypto.com/apidocs/#query-order-signedFlag
   * @description fetches information on an order made by the user
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOrder(std::any id, std::any symbol = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any request = ccxt::dict{
                     {std::string("orderId"), id},
                 };
                 std::any response = awaitValue(this->privateGetOpenV1Orders(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "code": 0,
                 //         "msg": "Success",
                 //         "data": {
                 //             "list": [{
                 //                 "orderId": "145221985",
                 //                 "clientId":
                 //                 "201515331fd64d03aedbe687a38152e3",
                 //                 "bOrderId": "35239632",
                 //                 "bOrderListId": "0",
                 //                 "symbol": "USDT_BIDR",
                 //                 "symbolType": 1,
                 //                 "side": 0,
                 //                 "type": 1,
                 //                 "price": "11907",
                 //                 "origQty": "2",
                 //                 "origQuoteQty": "23814",
                 //                 "executedQty": "0",
                 //                 "executedPrice": "0",
                 //                 "executedQuoteQty": "0",
                 //                 "timeInForce": 1,
                 //                 "stopPrice": "0",
                 //                 "icebergQty": "0",
                 //                 "status": 0,
                 //                 "createTime": 1662699360000
                 //             }]
                 //         },
                 //         "timestamp": 1662710056523
                 //     }
                 //
                 std::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::dict{});
                 std::any list =
                     this->safeValue(data, std::string("list"), ccxt::list{});
                 std::any rawOrder = this->safeDict(list, 0, ccxt::dict{});
                 return this->parseOrder(rawOrder);
               })
        .share();
  }

  /**
   * @method
   * @name tokocrypto#fetchOrders
   * @see https://www.tokocrypto.com/apidocs/#all-orders-signedFlag
   * @description fetches information on multiple orders made by the user
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOrders(std::any symbol = std::any{}, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " fetchOrders() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any response = awaitValue(this->privateGetOpenV1Orders(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "code": 0,
                 //         "msg": "success",
                 //         "data": {
                 //             "list": [
                 //                 {
                 //                     "orderId": "4", // order id
                 //                     "bOrderId": "100001", // binance order
                 //                     id "bOrderListId": -1, // Unless part of
                 //                     an OCO, the value will always be -1.
                 //                     "clientId":
                 //                     "1aa4f99ad7bc4fab903395afd25d0597", //
                 //                     client custom order id "symbol":
                 //                     "ADA_USDT", "symbolType": 1, "side": 1,
                 //                     "type": 1,
                 //                     "price": "0.1",
                 //                     "origQty": "10",
                 //                     "origQuoteQty": "1",
                 //                     "executedQty": "0",
                 //                     "executedPrice": "0",
                 //                     "executedQuoteQty": "0",
                 //                     "timeInForce": 1,
                 //                     "stopPrice": "0.0000000000000000",
                 //                     "icebergQty": "0.0000000000000000",
                 //                     "status": 0,
                 //                     "isWorking": 0,
                 //                     "createTime": 1572692016811
                 //                 }
                 //             ]
                 //         },
                 //         "timestamp": 1572860756458
                 //     }
                 //
                 std::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::dict{});
                 std::any orders =
                     this->safeList(data, std::string("list"), ccxt::list{});
                 return this->parseOrders(orders, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name tokocrypto#fetchOpenOrders
   * @see https://www.tokocrypto.com/apidocs/#all-orders-signedFlag
   * @description fetch all unfilled currently open orders
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of  open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOpenOrders(std::any symbol = std::any{}, std::any since = std::any{},
                  std::any limit = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any request = ccxt::dict{
                            {std::string("type"), 1},
                        }; // -1 = all, 1 = open, 2 = closed
                        return awaitValue(
                            this->fetchOrders(symbol, since, limit,
                                              this->extend(request, params)));
                      })
        .share();
  }

